import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Blocklist approach - known to be bypassable
    private static final Pattern BLOCKED_KEYWORDS = Pattern.compile(
        "(union|select|insert|update|delete|drop|alter|exec|execute|xp_)",
        Pattern.CASE_INSENSITIVE
    );

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Input "sanitization" - blocklist filtering
        if (reportType != null && BLOCKED_KEYWORDS.matcher(reportType).find()) {
            resp.sendError(400, "Invalid input detected");
            return;
        }
        if (department != null && BLOCKED_KEYWORDS.matcher(department).find()) {
            resp.sendError(400, "Invalid input detected");
            return;
        }

        // Sort column whitelist - but only checks prefix
        if (sortCol != null && !sortCol.startsWith("col_")) {
            sortCol = "col_date";
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Vulnerable: string concatenation in SQL
            String sql = "SELECT r.id, r.title, r.created_at, r.amount " +
                         "FROM reports r " +
                         "WHERE r.report_type = '" + reportType + "' " +
                         "AND r.department = '" + department + "' ";

            if (dateRange != null && dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
                String[] parts = dateRange.split("_");
                sql += "AND r.created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "' ";
            }

            sql += "ORDER BY " + sortCol + " DESC LIMIT 100";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\": ").append(rs.getInt("id"))
                    .append(", \"title\": \"").append(rs.getString("title"))
                    .append("\", \"date\": \"").append(rs.getString("created_at"))
                    .append("\", \"amount\": ").append(rs.getDouble("amount"))
                    .append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            // Verbose error - information disclosure
            out.print("{\"error\": \"" + e.getMessage().replace("\"", "'") + "\"}");
            resp.setStatus(500);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST handler for report generation - also vulnerable
        String templateId = req.getParameter("template");
        String customFilter = req.getParameter("filter");

        if (customFilter != null && customFilter.length() > 200) {
            resp.sendError(400, "Filter too long");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String sql = "SELECT * FROM report_templates WHERE id = '" + templateId +
                         "' AND active = 1";
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            if (rs.next()) {
                String baseQuery = rs.getString("base_query");
                // Appends user filter directly to stored query
                if (customFilter != null) {
                    baseQuery += " AND " + customFilter;
                }
                ResultSet data = stmt.executeQuery(baseQuery);
                resp.getWriter().print("{\"status\": \"generated\", \"rows\": " +
                    data.getFetchSize() + "}");
            }
        } catch (SQLException e) {
            resp.getWriter().print("{\"error\": \"query failed\"}");
            resp.setStatus(500);
        }
    }
}
